import { it } from 'vitest';
import request from 'supertest';
import { createApp } from '../src/app.js';

it('diagnostico tmp: status de cada passo do cenario R1/R2', async () => {
  const app = createApp({ modoTeste: true });

  const reset = await request(app).post('/_teste/reset');
  console.log('POST /_teste/reset ->', reset.status);

  const criacao = await request(app)
    .post('/atividades')
    .set('X-Usuario', 'org-ana')
    .send({
      titulo: 'Minicurso para emissão',
      tipo: 'minicurso',
      salaId: 'lab-3',
      vagas: 10,
      encontros: [{ inicio: '2026-10-19T19:00:00-03:00', fim: '2026-10-19T22:00:00-03:00' }]
    });
  console.log('POST /atividades ->', criacao.status, JSON.stringify(criacao.body));
  const atividadeId = criacao.body?.id;

  const inscricao = await request(app)
    .post(`/atividades/${atividadeId}/inscricoes`)
    .set('X-Usuario', 'p-carla');
  console.log('POST /atividades/:id/inscricoes ->', inscricao.status, JSON.stringify(inscricao.body));

  const codigo = await request(app)
    .get('/encontros/enc_qualquer/codigo')
    .set('X-Usuario', 'org-ana');
  console.log('GET /encontros/:id/codigo ->', codigo.status, JSON.stringify(codigo.body));

  const presenca = await request(app)
    .post('/encontros/enc_qualquer/presencas')
    .set('X-Usuario', 'p-carla')
    .send({ codigo: 'X' });
  console.log('POST /encontros/:id/presencas ->', presenca.status, JSON.stringify(presenca.body));

  const certificado = await request(app)
    .post(`/atividades/${atividadeId}/certificado`)
    .set('X-Usuario', 'p-carla');
  console.log('POST /atividades/:id/certificado ->', certificado.status, JSON.stringify(certificado.body));

  (app as any).close();
});

